function validate([n, paths]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is an integer from 1 to 10^5.';
  if (!Array.isArray(paths) || paths.length < 2 || paths.length > 100000) return 'paths needs at least 2 routes.';
  let total = 0;
  for (const path of paths) {
    if (!Array.isArray(path) || path.length < 1) return 'Each route visits at least one city.';
    total += path.length;
    for (let j = 0; j < path.length; j++) {
      if (!Number.isInteger(path[j]) || path[j] < 0 || path[j] >= n) return 'Every city is an integer from 0 to n - 1.';
      if (j > 0 && path[j] === path[j - 1]) return 'A route never lists the same city twice in a row.';
    }
  }
  if (total > 100000) return 'All routes together hold at most 10^5 cities.';
  return null;
}

