function longestCommonSubpath(n, paths) {
  const MOD1 = 1000000007;
  const MOD2 = 998244353;
  const BASE1 = 100003;
  const BASE2 = 100019;

  function windowHashes(path, length) {
    const hashes = new Set();
    let power1 = 1;
    let power2 = 1;
    for (let i = 0; i < length; i++) {
      power1 = power1 * BASE1 % MOD1;
      power2 = power2 * BASE2 % MOD2;
    }
    let hash1 = 0;
    let hash2 = 0;
    for (let i = 0; i < path.length; i++) {
      hash1 = (hash1 * BASE1 + path[i] + 1) % MOD1;
      hash2 = (hash2 * BASE2 + path[i] + 1) % MOD2;
      if (i >= length) {
        hash1 = (hash1 - (path[i - length] + 1) * power1 % MOD1 + MOD1) % MOD1;
        hash2 = (hash2 - (path[i - length] + 1) * power2 % MOD2 + MOD2) % MOD2;
      }
      if (i >= length - 1) {
        hashes.add(hash1 + ',' + hash2);
      }
    }
    return hashes;
  }

  function sharedByAll(length) {
    let common = windowHashes(paths[0], length);
    for (let p = 1; p < paths.length && common.size > 0; p++) {
      const next = windowHashes(paths[p], length);
      common = new Set([...common].filter(key => next.has(key)));
    }
    return common.size > 0;
  }

  let low = 0;
  let high = Math.min(...paths.map(path => path.length));
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    if (sharedByAll(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

