function longestCommonSubpath(n, paths) {
  // Collect every subpath of every route as text and intersect the sets.
  const subpaths = path => {
    const found = new Set();
    for (let i = 0; i < path.length; i++)
      for (let j = i + 1; j <= path.length; j++) found.add(path.slice(i, j).join(' '));
    return found;
  };
  let common = subpaths(paths[0]);
  for (const path of paths.slice(1)) {
    const found = subpaths(path);
    common = new Set([...common].filter(text => found.has(text)));
  }
  let best = 0;
  for (const text of common) best = Math.max(best, text.split(' ').length);
  return best;
}

