function generate(rand, size) {
  const large = size === 'large';
  const many = large && rand() < 0.35;
  const m = many ? 300 + Math.floor(rand() * 700) : large ? 2 + Math.floor(rand() * 9) : 2 + Math.floor(rand() * 3);
  const roll = rand();
  const n = !large && roll < 0.1 ? 1 : roll < 0.5 ? 2 + Math.floor(rand() * 3) : large && roll < 0.8 ? 100000 : 5 + Math.floor(rand() * 20);
  if (n === 1) return [1, Array.from({ length: m }, () => [0])];
  // Next city: anything except the previous one.
  const step = prev => { const c = Math.floor(rand() * (n - 1)); return c >= prev ? c + 1 : c; };
  const walk = (start, length) => { const out = []; let prev = start; for (let k = 0; k < length; k++) { prev = step(prev); out.push(prev); } return out; };
  const cap = large ? Math.min(2000, Math.floor(18000 / m)) : 6;
  const planted = rand() < 0.75;
  let segment = [];
  if (planted) {
    const s = 1 + Math.floor(rand() * Math.min(cap, large ? 1500 : 3));
    const start = Math.floor(rand() * n);
    segment = [start, ...walk(start, s - 1)];
  }
  const paths = [];
  for (let i = 0; i < m; i++) {
    const length = Math.max(1, segment.length) + Math.floor(rand() * (cap - Math.max(1, segment.length) + 1));
    if (!planted) {
      const start = Math.floor(rand() * n);
      paths.push([start, ...walk(start, length - 1)]);
      continue;
    }
    const before = Math.floor(rand() * (length - segment.length + 1));
    const after = length - segment.length - before;
    // Walk away from the planted segment in both directions so no city repeats next to itself.
    paths.push([...walk(segment[0], before).reverse(), ...segment, ...walk(segment[segment.length - 1], after)]);
  }
  return [n, paths];
}
